import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validatorOptions = {strict: false, validateFormats: false};
  private readonly validator = new Ajv(this.validatorOptions as unknown as ConstructorParameters<typeof Ajv>[0]);
  private readonly compiledSchemas = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    const cached = this.compiledSchemas.get(schema);
    if (cached) return cached;
    try {
      const compiled = this.validator.compile(schema);
      this.compiledSchemas.set(schema, compiled);
      return compiled;
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${name}`, {cause: error});
    }
  }

  private validationPath(error: ErrorObject): string {
    const rawPath =
      'instancePath' in error ? String(error.instancePath) : 'dataPath' in error ? String(error.dataPath) : '';
    if (!rawPath.startsWith('/')) return rawPath.replace(/^\./, '');
    const parts = rawPath.slice(1).split('/');
    return parts
      .map((part, index) => {
        const name = part.replace(/~1/g, '/').replace(/~0/g, '~');
        return /^\d+$/.test(name) ? `[${name}]` : index === 0 ? name : `.${name}`;
      })
      .join('');
  }

  private validationFailure(error: ErrorObject): string {
    const path = this.validationPath(error);
    const at = (field: string): string => (path ? `${path}.` : '') + field;
    if (error.keyword === 'required') {
      const field = String('missingProperty' in error.params ? error.params.missingProperty : '');
      return `${at(field)} is required`;
    }
    if (error.keyword === 'additionalProperties') {
      const field = String('additionalProperty' in error.params ? error.params.additionalProperty : '');
      return `${at(field)} violates additionalProperties`;
    }
    const field = path || 'input';
    if (error.keyword === 'type') return `${field} must be ${String('type' in error.params ? error.params.type : '')}`;
    if (error.keyword === 'enum') return `${field} must match a declared enum value`;
    return `${field} violates ${error.keyword}`;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const staticValidator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for the validation and error contract. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate =
      tool.staticValidator ?? this.compileSchema(name, this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validate(input)) {
      const error = validate.errors?.[0];
      const result = error ? this.validationFailure(error) : 'input violates schema';
      log.warn('tool', 'input rejected', {name, reason: result});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry rejection paths', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#4
  it('names a slash-bearing property without exposing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', properties: {'personal/data': {type: 'string'}}},
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('lookup', {'personal/data': 123456789});

    expect({
      path: response.result.includes('personal/data'),
      type: response.result.includes('string'),
      leaked: response.result.includes('123456789'),
    }).toEqual({path: true, type: true, leaked: false});
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#5
  it('names an explicitly forbidden extra property without exposing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', additionalProperties: false},
      },
      async () => 'unreachable'
    );

    const personalIdKey = 'personal_id';
    const response = await registry.execute('lookup', {[personalIdKey]: 'secret-123'});

    expect({
      path: response.result.includes('personal_id'),
      constraint: response.result.includes('additionalProperties'),
      leaked: response.result.includes('secret-123'),
    }).toEqual({path: true, constraint: true, leaked: false});
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#4
  it('names an array element field with its index and expected type', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'forecast',
        description: 'Get forecasts',
        inputSchema: {
          type: 'object',
          properties: {
            forecasts: {type: 'array', items: {type: 'object', properties: {location: {type: 'string'}}}},
          },
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('forecast', {forecasts: [{location: 12345}]});

    expect(response.result).toBe('forecasts[0].location must be string');
  });
});

describe('ToolRegistry schema compilation', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#10
  it('keeps the schema compiled at registration when a static definition changes', async () => {
    const registry = new ToolRegistry();
    const definition = {
      name: 'weather',
      description: 'Get weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(definition, async input => {
      inputs.push(input);
      return 'forecast';
    });
    definition.inputSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['days']};

    const response = await registry.execute('weather', {location: 'Paris'});

    expect({response, inputs}).toEqual({response: {result: 'forecast'}, inputs: [{location: 'Paris'}]});
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#9
  it('rejects an invalid static input schema when registering its named tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Get weather',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

describe('ToolRegistry dynamic schema validation', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#11
  it('uses each current schema and compiles each schema object once', async () => {
    const registry = new ToolRegistry();
    const locationSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const forecastSchema = {
      type: 'object',
      properties: {days: {type: 'number'}},
      required: ['days'],
    };
    let schema: Record<string, unknown> = locationSchema;
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: schema}),
      async input => {
        inputs.push(input);
        return 'forecast';
      }
    );
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const missingLocation = await registry.execute('weather', {});
      const location = await registry.execute('weather', {location: 'Paris'});
      schema = forecastSchema;
      const missingDays = await registry.execute('weather', {location: 'Paris'});
      const days = await registry.execute('weather', {days: 2});
      const calls = compile.mock.calls;

      expect({
        missingLocation: missingLocation.result.includes('location'),
        location: location.result,
        missingDays: missingDays.result.includes('days'),
        days: days.result,
        inputs,
        compileCalls: calls.length,
      }).toEqual({
        missingLocation: true,
        location: 'forecast',
        missingDays: true,
        days: 'forecast',
        inputs: [{location: 'Paris'}, {days: 2}],
        compileCalls: 2,
      });
    } finally {
      compile.mockRestore();
    }
  });
});

import {jest} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import {AIError} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

// One expect per test needs the rejection as a value rather than a matcher.
const outcomeOf = (call: Promise<unknown>): Promise<string> =>
  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function createErrorProvider(error: Error): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

type RecordedHook =
  | 'beforeSession'
  | 'beforeUserInput'
  | 'afterUserInput'
  | 'beforeModelResponse'
  | 'afterModelResponse'
  | 'afterSession'
  | 'onError';

// Only the named hooks are installed: one that merely exists changes the observed order.
const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
  const all: Required<OrchestratorHooks> = {
    beforeSession: async () => void callOrder.push('beforeSession'),
    beforeUserInput: async (_session, msg) => {
      callOrder.push('beforeUserInput');
      return msg;
    },
    afterUserInput: async () => void callOrder.push('afterUserInput'),
    beforeModelResponse: async (_session, systemPrompt) => {
      callOrder.push('beforeModelResponse');
      return systemPrompt;
    },
    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
    afterSession: async () => void callOrder.push('afterSession'),
    onError: async () => void callOrder.push('onError'),
  };

  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
};

// Records what the orchestrator actually sent, for tests that assert on the request.
const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
  const sent = {systemPrompt: '', lastUserContent: ''};

  return {
    sent,
    provider: {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        sent.systemPrompt = params.systemPrompt;
        const last = params.messages[params.messages.length - 1];
        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
        yield {type: 'text', text: 'ok'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    },
  };
};

describe('ChatOrchestrator hooks', () => {
  describe('beforeSession', () => {
    it('called before anything else', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder[0]).toBe('beforeSession');
    });
  });

  describe('afterSession', () => {
    it('called after everything completes', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
    });

    it('called even when an error occurs', async () => {
      let afterSessionCalled = false;
      const hooks: OrchestratorHooks = {
        onError: async () => {},
        afterSession: async () => {
          afterSessionCalled = true;
        },
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
        hooks,
      });
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
    });
  });

  describe('beforeUserInput', () => {
    it('receives the last user message content', async () => {
      let receivedMessage = '';
      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_session, userMessage) => {
          receivedMessage = userMessage;
          return userMessage;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('my answer'));

      expect(receivedMessage).toBe('my answer');
    });

    it('modifies user message when returning different value', async () => {
      const {provider, sent} = capturingProvider();

      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_session, _msg) => 'sanitized input',
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('raw input'));

      expect(sent.lastUserContent).toBe('sanitized input');
    });
  });

  describe('afterUserInput', () => {
    it('receives user message after any beforeUserInput modification', async () => {
      let afterReceived = '';
      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_s, _msg) => 'modified',
        afterUserInput: async (_s, msg) => {
          afterReceived = msg;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('original'));

      expect(afterReceived).toBe('modified');
    });
  });

  describe('beforeModelResponse', () => {
    it('replaces system prompt with returned value', async () => {
      const {provider, sent} = capturingProvider();

      const hooks: OrchestratorHooks = {
        beforeModelResponse: async (_session, _basePrompt) => 'Custom prompt for this question',
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(sent.systemPrompt).toBe('Custom prompt for this question');
    });
  });

  describe('afterModelResponse', () => {
    it('receives collected response text and usage', async () => {
      const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
      let receivedText = '';
      let receivedUsage: UsageMetadata | undefined;

      const hooks: OrchestratorHooks = {
        afterModelResponse: async (_session, text, u) => {
          receivedText = text;
          receivedUsage = u;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('hello world', usage), promptBuilder, undefined, {
        hooks,
      });
      await orchestrator.processMessage(createSession('hi'));

      expect({receivedText, receivedUsage}).toEqual({receivedText: 'hello world', receivedUsage: usage});
    });

    it('not called when stream throws', async () => {
      let afterCalled = false;
      const hooks: OrchestratorHooks = {
        afterModelResponse: async () => {
          afterCalled = true;
        },
        onError: async () => {},
      };

      const orchestrator = createChatOrchestrator(
        createErrorProvider(new AIError('fail', 'TEST')),
        promptBuilder,
        undefined,
        {hooks}
      );
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, afterCalled}).toEqual({outcome: 'fail', afterCalled: false});
    });
  });

  describe('onError', () => {
    it('called with session and error when stream fails', async () => {
      let receivedError: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          receivedError = error;
        },
      };

      const orchestrator = createChatOrchestrator(
        createErrorProvider(new AIError('rate limited', 'RATE_LIMITED')),
        promptBuilder,
        undefined,
        {hooks}
      );
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, receivedErrorMessage: receivedError?.message}).toEqual({
        outcome: 'rate limited',
        receivedErrorMessage: 'rate limited',
      });
    });

    it('error still propagates after onError hook', async () => {
      const hooks: OrchestratorHooks = {
        onError: async () => {},
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
        hooks,
      });
      await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
    });
  });

  describe('full lifecycle order', () => {
    it('calls all hooks in correct order', async () => {
      const callOrder: string[] = [];
      const usage: UsageMetadata = {inputTokens: 5, outputTokens: 3, totalTokens: 8};

      const hooks: OrchestratorHooks = {
        beforeSession: async () => {
          callOrder.push('beforeSession');
        },
        beforeUserInput: async (_s, msg) => {
          callOrder.push('beforeUserInput');
          return msg;
        },
        afterUserInput: async () => {
          callOrder.push('afterUserInput');
        },
        beforeModelResponse: async (_s, p) => {
          callOrder.push('beforeModelResponse');
          return p;
        },
        afterModelResponse: async () => {
          callOrder.push('afterModelResponse');
        },
        afterSession: async () => {
          callOrder.push('afterSession');
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('ok', usage), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder).toEqual([
        'beforeSession',
        'beforeUserInput',
        'afterUserInput',
        'beforeModelResponse',
        'afterModelResponse',
        'afterSession',
      ]);
    });

    it('error path calls onError then afterSession', async () => {
      const callOrder: string[] = [];

      const hooks = recordingHooks(callOrder, [
        'beforeSession',
        'beforeUserInput',
        'afterUserInput',
        'beforeModelResponse',
        'afterModelResponse',
        'onError',
        'afterSession',
      ]);

      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('fail')), promptBuilder, undefined, {
        hooks,
      });
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, callOrder}).toEqual({
        outcome: 'fail',
        callOrder: [
          'beforeSession',
          'beforeUserInput',
          'afterUserInput',
          'beforeModelResponse',
          'onError',
          'afterSession',
        ],
      });
    });
  });

  describe('no hooks', () => {
    it('works without any hooks configured', async () => {
      const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder);
      const result = await orchestrator.processMessage(createSession('hello'));
      expect(result).toBe('hello back');
    });
  });
});

// One scripted round per sendMessage call, to drive the tool loop round by round.
const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
  const chunks: MessageChunk[] = [];
  for await (const chunk of stream) chunks.push(chunk);
  return chunks;
};

describe('ChatOrchestrator tool loop', () => {
  it('runs another round after a tool call and streams both rounds in order', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'the answer'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
  });

  it('stops after one round when nothing asked for a tool', async () => {
    const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'x'}));

    const text = await orchestrator.processMessage(createSession('ask'));

    expect(text).toBe('done');
  });

  it('stops asking for tools once maxToolRounds is spent', async () => {
    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
    const orchestrator = createChatOrchestrator(
      scriptedProvider(alwaysTools),
      promptBuilder,
      registryReturning({result: 'again'}),
      {maxToolRounds: 2}
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(3);
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#12
  it('executes no more than maxToolRounds rejected tool calls', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'lookup', description: 'Look up a record', inputSchema: {type: 'object', required: ['id']}},
      async () => 'found'
    );
    const execute = jest.spyOn(registry, 'execute');
    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
    const orchestrator = createChatOrchestrator(scriptedProvider(alwaysTools), promptBuilder, registry, {
      maxToolRounds: 2,
    });

